inline void b1Fight(G2NaturalDriver& r){
 auto& g=r.game;int fired=0,readyTick=0;const bool cycle=g.session().variable(635)==1||g.session().difficulty()!="normal";
 for(int n=0;n<30000;++n){auto& session=g.session();need(session.hp()>0&&g.mode()==ApplicationMode::Playing,"06 legal battle died");std::vector<G2NaturalDriver::Target> alive;for(const auto& view:g.enemyStates()){const auto& e=g.content().enemies.at(view.id);if(!session.flag(e.deadFlag)){alive.push_back({view.id,view.damage,view.sourceState,e.deadFlag});}}if(alive.empty()){r.lower();std::cout<<"06 real battle fired="<<fired<<" HP="<<session.hp()<<'\n';return;}
  if(cycle&&session.hp()<75&&r.healingItem()&&g.foreground()==ForegroundKind::None){
   r.lowerForMenu(readyTick);r.healTo(100);continue;
  }
  const int weapon=session.equipped(1),before=session.magazine(weapon);InputFrame in;
  if(g.foreground()!=ForegroundKind::None||g.dialogue().active()){if(n%8==0){in=key();}}
  else if(!g.raised()){in=key(InputAction::Weapon);}
  else{const auto p=g.world().player().motion.tile();const auto it=std::min_element(alive.begin(),alive.end(),[&](const auto& a,const auto& b){auto x=findCharacter(g.world(),a.id).motion.tile(),y=findCharacter(g.world(),b.id).motion.tile();return std::abs(x.x-p.x)+std::abs(x.y-p.y)<std::abs(y.x-p.x)+std::abs(y.y-p.y);});const auto t=findCharacter(g.world(),it->id).motion.tile();const int dx=t.x-p.x,dy=t.y-p.y;auto face=std::abs(dx)>std::abs(dy)?(dx>0?Direction::Right:Direction::Left):(dy>0?Direction::Down:Direction::Up);
   const bool hunter=g.content().enemies.at(it->id).rules.at("behavior")=="hunter";
   if(it->damage>=100||it->state>=100){}
   else if((dx&&dy)||std::abs(dx)+std::abs(dy)>3){for(auto side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){auto move=next(g.world(),adjacentTile(t,side));if(move){in.movement=move;break;}}}
   else if(g.world().player().motion.facing()!=face){in.buttons[int(InputAction::Weapon)].held=true;in.movement=face;}
   else if((!hunter||it->state<=2||it->state==11)&&n%24==0){if(cycle&&before==0&&!session.hasReserve()){r.lowerForMenu(readyTick);r.equipAvailable({20,15,19,21});continue;}need(before>0||session.hasReserve(),"06 legal magnum/reserve exhausted");in=key(InputAction::Attack);}
   if(n%500==0){std::cout<<"06 fight map="<<g.mapId()<<" n="<<n<<" p="<<p.x<<","<<p.y<<" target="<<it->id<<" state="<<it->state<<" damage="<<it->damage<<" HP="<<session.hp()<<" weapon="<<weapon<<" magazine="<<before<<" reserve40="<<session.count(40)<<'\n';}
  }
  r.tick(in);const int used=std::max(0,before-session.magazine(weapon));fired+=used;if(used){readyTick=r.ticks+r.fireRecoveryTicks(weapon);std::cout<<"06 shot weapon="<<weapon<<" n="<<n<<" used="<<used<<" magazine="<<session.magazine(weapon)<<" damage="<<session.variable(89)<<","<<session.variable(103)<<","<<session.variable(117)<<'\n';}
 }
 throw std::runtime_error("06 legal fight stalled");
}
